begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(19);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18500000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-cancel-confirm@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18500000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18500000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18500000-0000-0000-0000-000000000004','18500000-0000-0000-0000-000000000001','18500000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18500000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18500000-0000-0000-0000-000000000005','18500000-0000-0000-0000-000000000001','18500000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18500000-0000-0000-0000-000000000006','18500000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18500000-0000-0000-0000-000000000007','18500000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18500000-0000-0000-0000-000000000008','18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18500000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18500000-0000-0000-0000-000000000003","session_id":"18500000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_cancel_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('cancel185-browser','cancel185-browser','18500000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18500000-0000-0000-0000-000000000009','18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000006','2026-11-02 00:00+00','2026-11-02 01:00+00','published');
select set_config('test.cancel',private.prepare_mcp_shift_cancel('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000008','cancel','synthetic')::text,true);
select set_config('test.stale',private.prepare_mcp_shift_cancel('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000008','cancel','synthetic')::text,true);
select set_config('test.delete',private.prepare_mcp_shift_cancel('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000009','soft_delete','synthetic')::text,true);
select ok(has_function_privilege('authenticated','public.confirm_mcp_shift_cancel(uuid)','execute') and not has_function_privilege('mcp_import','public.confirm_mcp_shift_cancel(uuid)','execute'),'only browser role may call confirmation RPC');
select ok(not has_function_privilege('mcp_import','private.confirm_mcp_shift_cancel(uuid)','execute') and not has_function_privilege('authenticated','private.confirm_mcp_shift_cancel(uuid)','execute'),'confirmation primitive is not exposed');
select throws_ok($$select public.confirm_mcp_shift_cancel(current_setting('test.cancel')::uuid)$$,'42501','proposal_unavailable','OAuth cannot confirm');
select is((select status from public.shifts where id='18500000-0000-0000-0000-000000000008'),'published','before confirmation shift unchanged');
select set_config('request.jwt.claims','{"sub":"18500000-0000-0000-0000-000000000001","role":"authenticated","session_id":"cancel185-browser"}',true);
select is(public.confirm_mcp_shift_cancel(current_setting('test.cancel')::uuid)->>'newly_updated','true','browser cancellation succeeds');
select is((select status from public.shifts where id='18500000-0000-0000-0000-000000000008'),'cancelled','shift is cancelled');
select is((select google_sync_status from public.shifts where id='18500000-0000-0000-0000-000000000008'),'pending_upsert','cancellation awaits sync');
select is(public.confirm_mcp_shift_cancel(current_setting('test.cancel')::uuid)->>'newly_updated','false','cancellation replay is idempotent');
select is((select count(*) from public.audit_events where action_type='shift.cancel' and resource_id='18500000-0000-0000-0000-000000000008'),1::bigint,'one cancellation audit');
select throws_ok($$select public.confirm_mcp_shift_cancel(current_setting('test.stale')::uuid)$$,'22023','proposal_changed','stale proposal is rejected');
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18500000-0000-0000-0000-000000000004';
select throws_ok($$select public.confirm_mcp_shift_cancel(current_setting('test.delete')::uuid)$$,'42501','proposal_unavailable','revoked OAuth cannot confirm');
update auth.oauth_consents set revoked_at=null where id='18500000-0000-0000-0000-000000000004';
select throws_ok($$select public.confirm_mcp_shift_cancel(current_setting('test.delete')::uuid)$$,'22023','retention_policy_required','deletion without policy rejected');
insert into public.retention_policies(organization_id,resource_type,retention_years,legal_basis,reviewed_at,reviewed_by) values ('18500000-0000-0000-0000-000000000002','shift',5,'synthetic',now(),'18500000-0000-0000-0000-000000000001');
create function pg_temp.reject_audit() returns trigger language plpgsql as $$begin raise exception 'synthetic audit failure'; end$$;
create trigger synthetic_audit_failure before insert on public.audit_events for each row execute function pg_temp.reject_audit();
select throws_ok($$select public.confirm_mcp_shift_cancel(current_setting('test.delete')::uuid)$$,'P0001','synthetic audit failure','audit failure aborts deletion');
select is((select deleted_at from public.shifts where id='18500000-0000-0000-0000-000000000009'),null::timestamptz,'audit failure rolls back deletion');
drop trigger synthetic_audit_failure on public.audit_events;
select is(public.confirm_mcp_shift_cancel(current_setting('test.delete')::uuid)->>'newly_updated','true','soft deletion succeeds with policy');
select ok((select deleted_at is not null and retention_until>clock_timestamp() and google_sync_status='pending_delete' from public.shifts where id='18500000-0000-0000-0000-000000000009'),'row retained with deadline and pending sync');
select is(public.confirm_mcp_shift_cancel(current_setting('test.delete')::uuid)->>'newly_updated','false','soft deletion replay is idempotent');
select is((select count(*) from public.audit_events where action_type='shift.bulk_soft_delete' and resource_id='18500000-0000-0000-0000-000000000009'),1::bigint,'one deletion audit');
select is((select count(*) from public.shifts where id='18500000-0000-0000-0000-000000000009'),1::bigint,'no physical deletion');
select * from finish();
rollback;
